sub('src/server/repositories/issue-repository.ts', '''/** Cascade behind `ProjectService.archiveProject`''', '''/**
 * Every live issue of a project, in issue-number order and never paged: the
 * clone must walk the whole project, however many issues it has.
 */
export async function listLiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(issues.number, issues.id)
    .all();

  // Labels are read in chunks so a large project stays under SQLite's
  // bound-parameter ceiling.
  const result: Issue[] = [];
  for (let at = 0; at < rows.length; at += 500) {
    const chunk = rows.slice(at, at + 500);
    const labels = await listLabelsForIssues(
      orgId,
      chunk.map((row) => row.id as IssueId),
    );
    for (const row of chunk) {
      result.push(toIssue(row, (labels[row.id] ?? []).map((l) => l.id)));
    }
  }
  return result;
}

/**
 * Inserts fresh copies of `sources` into `toProjectId` as one transaction:
 * numbered from 1 in the order given, in `status`, unassigned, unlinked, with
 * no start or completion time and authored by `authorId`. Only the title,
 * description, priority, estimate, due date and labels are carried over.
 */
export async function insertIssueCopies(
  orgId: OrgId,
  toProjectId: ProjectId,
  sources: readonly Issue[],
  authorId: UserId,
  status: IssueStatus,
): Promise<readonly Issue[]> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const copies: Issue[] = [];
    let number = 0;

    for (const source of sources) {
      number += 1;
      const row = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId,
          projectId: toProjectId,
          number,
          title: source.title,
          description: source.description,
          status,
          priority: source.priority,
          authorId,
          assigneeId: null,
          parentId: null,
          estimate: source.estimate,
          dueAt: source.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      if (source.labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            source.labelIds.map((labelId) => ({
              orgId,
              issueId: row.id,
              labelId,
            })),
          )
          .run();
      }

      copies.push(toIssue(row, source.labelIds));
    }

    return copies;
  });
}

